import { useState, useEffect } from "react";

const C = {
  olive: "#4E5A3E", oliveMid: "#6B7C3E", oliveLt: "#8FA65D",
  brown: "#7A4A34", brownDk: "#5C3626", brownLt: "#A0622D",
  cream: "#F3EDE2", creamLt: "#FAF7F2", creamDk: "#E8E0D2",
  mustard: "#C4952E", white: "#FFFFFF", dark: "#1C1C1C",
  charcoal: "#3A3A3A", gray: "#8A8578", grayLt: "#B8B1A5",
};

const PHOTO = "data:image/png;base64,";
const BRAND_IMG = "data:image/png;base64,";

const GeoShape = ({ style = {} }) => (
  <svg viewBox="0 0 200 260" fill="none" style={{ position: "absolute", opacity: 0.12, ...style }}>
    <path d="M100 0 C100 0, 200 60, 200 160 C200 220, 155 260, 100 260 C45 260, 0 220, 0 160 L0 100 C0 45, 45 0, 100 0Z" fill={C.olive} />
    <circle cx="140" cy="40" r="28" fill={C.brown} opacity="0.7" />
    <path d="M60 20 Q80 -10, 100 20" stroke={C.brown} strokeWidth="1.5" fill="none" opacity="0.5" />
  </svg>
);
const GeoSmall = ({ style = {} }) => (
  <svg viewBox="0 0 120 150" fill="none" style={{ position: "absolute", opacity: 0.08, ...style }}>
    <rect x="10" y="30" width="80" height="110" rx="40" fill={C.olive} />
    <circle cx="90" cy="30" r="18" fill={C.brown} opacity="0.6" />
  </svg>
);
const TSMono = ({ size = 40, color = C.olive }) => (
  <svg width={size} height={size} viewBox="0 0 60 60"><text x="4" y="46" fontFamily="'Playfair Display', serif" fontSize="42" fontWeight="700" fill={color} letterSpacing="-3">TS</text></svg>
);
const ThinLine = ({ color = C.grayLt, width = "60px", style = {} }) => (
  <div style={{ width, height: 1, background: color, ...style }} />
);

const go = id => document.getElementById(id)?.scrollIntoView({ behavior: "smooth", block: "start" });
const Sec = ({ id, bg = C.creamLt, children, style = {} }) => <section id={id} style={{ position: "relative", overflow: "hidden", background: bg, ...style }}>{children}</section>;
const Inner = ({ children, style = {} }) => <div style={{ position: "relative", zIndex: 2, maxWidth: 1080, margin: "0 auto", padding: "80px 32px", ...style }}>{children}</div>;
const Label = ({ t, color = C.brown }) => <div style={{ fontFamily: "'Nunito Sans', sans-serif", fontSize: 11, fontWeight: 700, letterSpacing: 4, textTransform: "uppercase", color, marginBottom: 12 }}>{t}</div>;
const Title = ({ children, color = C.olive, style = {} }) => <h2 style={{ fontFamily: "'Playfair Display', serif", fontSize: "clamp(30px, 4.5vw, 46px)", fontWeight: 700, color, lineHeight: 1.12, margin: "0 0 20px", ...style }}>{children}</h2>;
const P = ({ children, style = {} }) => <p style={{ fontFamily: "'Nunito Sans', sans-serif", fontSize: 16, lineHeight: 1.8, color: C.charcoal, margin: "0 0 16px", ...style }}>{children}</p>;
const Btn = ({ children, bg = C.brown, color = C.white, onClick, style = {} }) => (
  <button onClick={onClick} style={{ background: bg, color, border: "none", borderRadius: 0, padding: "14px 36px", fontFamily: "'Nunito Sans', sans-serif", fontSize: 13, fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase", cursor: "pointer", transition: "all 0.3s", ...style }}
    onMouseEnter={e => { e.currentTarget.style.opacity = "0.88"; e.currentTarget.style.transform = "translateY(-1px)"; }}
    onMouseLeave={e => { e.currentTarget.style.opacity = "1"; e.currentTarget.style.transform = ""; }}>{children}</button>
);
const BtnOutline = ({ children, color = C.olive, onClick, style = {} }) => (
  <button onClick={onClick} style={{ background: "transparent", color, border: `1.5px solid ${color}`, borderRadius: 0, padding: "13px 34px", fontFamily: "'Nunito Sans', sans-serif", fontSize: 13, fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase", cursor: "pointer", transition: "all 0.3s", ...style }}
    onMouseEnter={e => { e.currentTarget.style.background = color; e.currentTarget.style.color = C.white; }}
    onMouseLeave={e => { e.currentTarget.style.background = "transparent"; e.currentTarget.style.color = color; }}>{children}</button>
);

function Nav() {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);
  useEffect(() => { const h = () => setScrolled(window.scrollY > 50); window.addEventListener("scroll", h); return () => window.removeEventListener("scroll", h); }, []);
  const links = [{ l: "About", id: "about" }, { l: "What I Do", id: "services" }, { l: "Courses & Books", id: "shop" }, { l: "Kind Words", id: "testimonials" }];
  return (
    <nav style={{ position: "fixed", top: 0, left: 0, right: 0, zIndex: 200, background: scrolled ? `${C.creamLt}F0` : "transparent", backdropFilter: scrolled ? "blur(14px)" : "none", borderBottom: scrolled ? `1px solid ${C.creamDk}` : "none", transition: "all 0.4s" }}>
      <div style={{ maxWidth: 1120, margin: "0 auto", padding: "16px 32px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <div style={{ cursor: "pointer", display: "flex", alignItems: "center", gap: 14 }} onClick={() => go("hero")}>
          <TSMono size={36} />
          <div>
            <div style={{ fontFamily: "'Playfair Display', serif", fontSize: 16, fontWeight: 700, color: C.olive, letterSpacing: 1, lineHeight: 1.1 }}>VISIONARY</div>
            <div style={{ fontFamily: "'Playfair Display', serif", fontSize: 16, fontWeight: 400, color: C.brown, letterSpacing: 1, lineHeight: 1.1 }}>ARCHITECT</div>
          </div>
        </div>
        <div className="desk-nav" style={{ display: "flex", gap: 4, alignItems: "center" }}>
          {links.map(l => <button key={l.id} onClick={() => go(l.id)} style={{ background: "none", border: "none", cursor: "pointer", padding: "8px 16px", fontFamily: "'Nunito Sans', sans-serif", fontSize: 12, fontWeight: 600, color: C.charcoal, letterSpacing: 1, textTransform: "uppercase", transition: "color 0.2s" }} onMouseEnter={e => e.currentTarget.style.color = C.brown} onMouseLeave={e => e.currentTarget.style.color = C.charcoal}>{l.l}</button>)}
          <a href="https://substack.com/@thevisionaryarchitect" target="_blank" rel="noopener noreferrer" style={{ padding: "8px 16px", fontFamily: "'Nunito Sans', sans-serif", fontSize: 12, fontWeight: 600, color: C.brown, letterSpacing: 1, textTransform: "uppercase", textDecoration: "none", transition: "opacity 0.2s" }} onMouseEnter={e => e.currentTarget.style.opacity = "0.7"} onMouseLeave={e => e.currentTarget.style.opacity = "1"}>Substack</a>
          <Btn onClick={() => go("contact")} style={{ padding: "10px 24px", fontSize: 11, marginLeft: 8 }}>Book a Call</Btn>
        </div>
        <button className="mob-btn" onClick={() => setOpen(!open)} style={{ display: "none", background: "none", border: "none", cursor: "pointer", fontSize: 22, color: C.olive }}>{open ? "\u2715" : "\u2630"}</button>
      </div>
      {open && <div className="mob-menu" style={{ background: C.creamLt, padding: "8px 32px 24px" }}>{links.map(l => <button key={l.id} onClick={() => { go(l.id); setOpen(false); }} style={{ display: "block", width: "100%", textAlign: "left", background: "none", border: "none", borderBottom: `1px solid ${C.creamDk}`, padding: "14px 0", fontFamily: "'Nunito Sans', sans-serif", fontSize: 14, fontWeight: 600, color: C.charcoal, letterSpacing: 1, textTransform: "uppercase", cursor: "pointer" }}>{l.l}</button>)}
        <a href="https://substack.com/@thevisionaryarchitect" target="_blank" rel="noopener noreferrer" style={{ display: "block", width: "100%", textAlign: "left", borderBottom: `1px solid ${C.creamDk}`, padding: "14px 0", fontFamily: "'Nunito Sans', sans-serif", fontSize: 14, fontWeight: 600, color: C.brown, letterSpacing: 1, textTransform: "uppercase", textDecoration: "none" }}>Substack</a>
        <button onClick={() => { go("contact"); setOpen(false); }} style={{ display: "block", width: "100%", textAlign: "left", background: "none", border: "none", padding: "14px 0", fontFamily: "'Nunito Sans', sans-serif", fontSize: 14, fontWeight: 700, color: C.olive, letterSpacing: 1, textTransform: "uppercase", cursor: "pointer" }}>Book a Call</button>
      </div>}
    </nav>
  );
}

